import {policy,vet,ticket,openPaper,closePaper,exitReason} from './engine.mjs';
import {scenarioTokens} from './scenarios.mjs';
const $=id=>document.getElementById(id);
const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2});
const price=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:3,maximumFractionDigits:4});
const percent=n=>(n*100).toFixed(1)+'%';
let ledger,candidates,events,selected='demo:alpha';
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function event(kind,message){events.unshift({at:new Date().toISOString(),kind,message});}
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
function freshCandidate(id){const t=candidates.find(t=>t.id===id);if(!t)throw Error('Candidate unavailable');return {...t,observedAt:Date.now()};}
function guard(fn){try{fn();render();}catch(e){notice(e.message,true);event('REFUSED',e.message);render();}}
function reset(){ledger={cash:1000,initialCash:1000,positions:[],closed:[],halted:false};candidates=scenarioTokens();events=[];selected='demo:alpha';$('scenario').value='balanced';event('CHIEF','New isolated paper session. Starting balance: $1,000.00.');event('SCAN','Four synthetic candidates inspected. One passed all evidence gates.');notice('Start with ALPHA: inspect its evidence, open a paper position, then apply a market scenario.');render();}
function open(id){guard(()=>{const p=openPaper(freshCandidate(id),ledger);event('FILL',`${p.symbol}: ${money(p.cost)} allocated; ${money(p.entryFee)} entry fee.`);notice('Paper position opened. Apply a rally or selloff scenario to see the exit rules act.');});}
function close(id){guard(()=>{const p=ledger.positions.find(p=>p.id===id);if(!p)throw Error('Position unavailable');const t=freshCandidate(p.tokenId),trade=closePaper(id,t.price,ledger);event('CLOSE',`${trade.symbol}: realized ${money(trade.pnl)} after both fees. Manual paper close.`);notice('Paper position closed. Both entry and exit fees are included in realized P&L.');});}
function applyScenario(){guard(()=>{const name=$('scenario').value;candidates=scenarioTokens(name);event('SCAN',`Scenario applied: ${$('scenario').selectedOptions[0].textContent}.`);let count=0;for(const p of [...ledger.positions]){const t=freshCandidate(p.tokenId),reason=exitReason(p,t.price);if(reason){const trade=closePaper(p.id,t.price,ledger,reason);count++;event('RISK',`${trade.symbol}: ${reason}; realized ${money(trade.pnl)} at ${price(t.price)}.`);}}notice(count?`${count} paper position closed by the risk rules. Inspect the realized result below.`:'Scenario updated. Review the evidence and prices before opening a paper position.');});}
function render(){
  const invested=ledger.positions.reduce((s,p)=>s+p.cost,0),marked=ledger.positions.reduce((s,p)=>s+p.quantity*freshCandidate(p.tokenId).price,0),equity=ledger.cash+marked,pnl=ledger.closed.reduce((s,t)=>s+t.pnl,0);
  $('metrics').replaceChildren(...[['Paper equity',money(equity),'Cash + marked positions'],['Available cash',money(ledger.cash),'Starting balance: $1,000'],['Open exposure',money(invested),'Maximum 10% of cost-based equity'],['Realized P&L',money(pnl),'Includes entry + exit fees']].map(([label,value,help])=>{const el=node('div',undefined,'metric');el.append(node('span',label,'metric-label'),node('strong',value),node('small',help));return el;}));
  $('scan-count').textContent=`${candidates.filter(t=>vet({...t,observedAt:Date.now()}).approved).length} / ${candidates.length} PASS`;
  $('candidates').replaceChildren(...candidates.map(t=>{const v=vet({...t,observedAt:Date.now()}),tr=node('tr'),asset=node('td'),b=node('button',t.symbol,'asset-button');b.onclick=()=>{selected=t.id;render();};b.setAttribute('aria-label',`Inspect ${t.symbol} evidence`);asset.append(b,node('small','DEMO / '+t.address));const numbers=node('td',price(t.price));numbers.append(node('small',money(t.liquidity)+' liquidity'));const status=node('td');status.append(node('span',v.approved?'Passed':`${v.failures.length} checks failed`,'status '+(v.approved?'pass':'reject')));const actions=node('td'),entry=node('button',v.approved?'Paper buy':'Inspect');if(v.approved){entry.disabled=ledger.halted||ledger.positions.some(p=>p.tokenId===t.id)||ticket(t,ledger)<1;entry.onclick=()=>open(t.id);entry.setAttribute('aria-label','Open ALPHA paper position');}else entry.onclick=()=>{selected=t.id;render();};actions.append(entry);tr.append(asset,numbers,status,actions);return tr;}));
  const t=freshCandidate(selected),v=vet(t),summary=node('p',`${t.symbol} · ${v.approved?'Passed all configured checks.':'Allocation refused until the failed checks are resolved.'}`,'evidence-summary'),checks=node('ul',undefined,'checks');
  const values=[['Contract controls',t.contractSafe===true?'Verified fixture':'Unknown',t.contractSafe===true],['Official account',t.socialVerified===true?'Verified fixture':'Unknown',t.socialVerified===true],['Largest account',t.topWalletFraction===null?'Unknown':percent(t.topWalletFraction),Number.isFinite(t.topWalletFraction)&&t.topWalletFraction<=policy.maxTopWallet],['Liquidity floor',money(t.liquidity),t.liquidity>=policy.minLiquidity],['Launch age',t.ageMinutes+' min',t.ageMinutes>=policy.minAgeMinutes&&t.ageMinutes<=policy.maxAgeMinutes],['Buy / sell count',t.buysH1+' / '+t.sellsH1,t.sellsH1>0&&t.buysH1>t.sellsH1]];
  for(const [label,value,pass] of values){const li=node('li');li.append(node('span',label),node('span',value,pass?'good':'bad'));checks.append(li);}
  $('evidence').replaceChildren(summary,checks);
  $('positions').replaceChildren(...ledger.positions.map(p=>{const t=freshCandidate(p.tokenId),net=p.quantity*t.price*(1-policy.feeBps/10000)-p.cost-p.entryFee,el=node('div',undefined,'position'),head=node('div',undefined,'position-head'),closeButton=node('button','Close paper position');closeButton.onclick=()=>close(p.id);head.append(node('strong',p.symbol),node('span',money(net)+' if closed',net>=0?'positive':'negative'));el.append(head,node('p',`${money(p.cost)} allocation · ${p.quantity.toFixed(2)} units · entry ${price(p.entryPrice)} · now ${price(t.price)}`,'position-details'),closeButton);return el;}));if(!ledger.positions.length)$('positions').append(node('p','No open positions. ALPHA is ready for a paper entry when exposure is available.','empty'));
  $('closed').replaceChildren(...ledger.closed.slice(-3).reverse().map(p=>{const el=node('div',undefined,'position'),head=node('div',undefined,'position-head');head.append(node('strong',p.symbol+' / CLOSED'),node('span',money(p.pnl),p.pnl>=0?'positive':'negative'));el.append(head,node('p',`${p.reason} · exit ${price(p.exitPrice)} · total fees ${money(p.entryFee+p.exitFee)}`,'position-details'));return el;}));
  const journal=node('div',undefined,'journal');for(const e of events){const el=node('div',undefined,'event'),text=node('div');text.append(node('b',e.kind),node('p',e.message));el.append(node('time',new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})),text);journal.append(el);}$('journal').replaceChildren(journal);$('event-count').textContent=events.length+' EVENTS';$('halt').textContent=ledger.halted?'Resume entries':'Pause entries';
}
$('advance').onclick=applyScenario;$('reset').onclick=reset;
$('halt').onclick=()=>{ledger.halted=!ledger.halted;event('CHIEF',ledger.halted?'New entries paused. Exit rules remain active.':'Paper entries resumed.');notice(ledger.halted?'New entries paused. You can still close positions or apply an exit scenario.':'Paper entries resumed.');render();};
$('export').onclick=()=>{const payload={mode:'synthetic-paper-demo',exportedAt:new Date().toISOString(),policy,ledger,events};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='trading-desk-demo-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Your demo journal was exported. It contains only this tab’s synthetic activity.');};
reset();
